    if (cx < Math.min(top[0], bot[0]) - 0.1 * ref || cx > Math.max(top[2], bot[2]) + 0.1 * ref) return false;
    return (b[3] <= top[1] + 0.05 * ref && b[3] > top[1] - 0.9 * ref) || (b[1] >= bot[3] - 0.05 * ref && b[1] < bot[3] + 0.9 * ref) ||
      (b[1] >= top[3] && b[3] <= bot[1]);
