  const opLike = u => u && u.k === 's' && (u.type === T_OP || RELATIONS.has(u.sym.label) || ['(', '[', ',', ':', '\\cdot'].includes(u.sym.label));
  const startsOperand = i => i === 0 || opLike(row[i - 1]);
