          if ((bb[3] - bb[1]) > 1.3 * Math.max(...set.map(v => (v.full || v.box)[3] - (v.full || v.box)[1])) + 0.1 * ref) continue;
          const right = bb[0] < x1 + 0.4 * ref && bb[0] > x1 - 0.5 * ref && cx < b[2] + 1.5 * ref;
          const left = bb[2] > x0 - 0.4 * ref && bb[2] < x0 + 0.5 * ref && cx > b[0] - 1.5 * ref;
