function relProbs(cur, u, ref) {
  return mlp(DATA.rel, relFeatures(cur.box, cur.type, u.full || u.box, u.type, ref, cur.k === 's' ? cur.sym.label : null, u.k === 's' ? u.sym.label : null));
}
