    let a = term(inAbs);
    for (let tk = peek(); tk && tk.t === 'op' && (tk.v === '+' || tk.v === '-'); tk = peek()) {
      next(); a = { t: tk.v === '+' ? 'add' : 'sub', a, b: term(inAbs) };
    }
