        if (tk.t === 'num' || tk.t === 'frac') sfail('a number straight after');
        // f(2): a letter just before a bracketed number is function notation, which has no answer here
        if (tk.t === 'open' && a.t === 'var' && !lettersIn(i)) sfail('function notation');
