    if (tk.t === 'pi') return { t: 'pi' };
    if (tk.t === 'frac') return { t: 'frac', a: sub(tk.num), b: sub(tk.den) };
    if (tk.t === 'root') return { t: 'root', a: sub(tk.body), idx: tk.idx ? sub(tk.idx) : null };
