  this.tex += label + (sub ? '_{' + sub + '}' : '') + (power > 1 ? '^{' + power + '}' : '');
  this.text += label.replace(/^\\/, '') + (sub ? '_' + sub : '') + (power > 1 ? '^' + power : '');
