  let places = Math.min(3, 15 - String(Math.floor(a)).length);
  if (a < 1) {
    const lead = (cutDigits(q, 20).frac.match(/^0*/) || [''])[0].length;
    if (lead > 12) sfail('too small');
    places = lead + 3;
  }
  const R = cutDigits(q, places);
