        delay: has('delay') ? +a('delay') : 450,
        settle: has('settle') ? +a('settle') : 0,
        auto: a('auto') !== 'false',
        boxes: has('boxes'),
        penOnly: has('pen-only'),
        lines: a('lines') !== 'false',
        degrees: a('degrees') !== 'false',
        smooth: has('smooth') && +a('smooth') > 0 ? +a('smooth') : 0,
